# --- [CELL 13]: ---

def sigmoid(z):
    return 1 / (1 + np.exp(-z))

def initialize_params(dim):
    w = np.zeros((dim, 1))
    b = 0
    return w, b

def model_optimize(w, b, X, Y):
    m = X.shape[0]


    final_result = sigmoid(np.dot(X, w) + b)
    cost = (-1/m) * np.sum(Y * np.log(final_result) + (1 - Y) * np.log(1 - final_result))


    dw = (1/m) * np.dot(X.T, (final_result - Y))
    db = (1/m) * np.sum(final_result - Y)

    grads = {"dw": dw, "db": db}

    return grads, cost

def model_train(X, Y, num_iterations, learning_rate):
    costs = []
    w, b = initialize_params(X.shape[1])

    for i in range(num_iterations):
        grads, cost = model_optimize(w, b, X, Y)

        dw = grads["dw"]
        db = grads["db"]

        w = w - learning_rate * dw
        b = b - learning_rate * db

        if i % 100 == 0:
            costs.append(cost)
            print("Cost after iteration %i: %f" % (i, cost))

    params = {"w": w, "b": b}
    grads = {"dw": dw, "db": db}

    return params, grads, costs

# --- [CELL 14]: ---

def model_predict(w, b, X, Y, learning_rate, no_iterations):
    costs = []
    for i in range(no_iterations):

        grads, cost = model_optimize(w,b,X,Y)

        dw = grads["dw"]
        db = grads["db"]

        w = w - (learning_rate * (dw.T))
        b = b - (learning_rate * db)


        if (i % 100 == 0):
            costs.append(cost)



    coeff = {"w": w, "b": b}
    gradient = {"dw": dw, "db": db}

    return coeff, gradient, costs

